(window.ABDI_PAKET = window.ABDI_PAKET || {})["skd.twk.bendera-bahasa-lagu.1"] = [{"i":2877,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":1,"q":"Menurut UU Nomor 24 Tahun 2009, Bendera Negara berbentuk empat persegi panjang dengan lebar … dari panjang.","e":"Pasal 4 UU Nomor 24 Tahun 2009 menyebut: “Bendera Negara Sang Merah Putih berbentuk empat persegi panjang dengan ukuran lebar 2/3 (dua-pertiga) dari panjang serta bagian atas berwarna merah dan bagian bawah berwarna putih yang kedua bagiannya berukuran sama.”\nBagian atas merah dan bagian bawah putih, kedua bagiannya berukuran sama.\nCara cepat: Semua ukuran resmi bendera berbanding 2 : 3, misalnya 120 cm × 180 cm untuk lapangan umum.","o":["1/2","2/3","3/5","3/4","4/5"],"s":[0,1,0,0,0],"w":["Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “2/3”, bukan “1/2”.","Benar. Ini sesuai Pasal 4 UU Nomor 24 Tahun 2009.","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “2/3”, bukan “3/5”.","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “2/3”, bukan “3/4”.","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “2/3”, bukan “4/5”."],"h":"Semua ukuran resmi bendera berbanding 2 : 3, misalnya 120 cm × 180 cm untuk lapangan umum."},{"i":2878,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Menurut UU Nomor 24 Tahun 2009, ukuran Bendera Negara untuk penggunaan di lapangan umum adalah …","e":"Pasal 4 UU Nomor 24 Tahun 2009 menyebut: “Bendera Negara sebagaimana dimaksud pada ayat (1) dibuat dengan ketentuan ukuran: 120 cm x 180 cm untuk penggunaan di lapangan umum”\nCara cepat: Semua ukuran resmi berbanding 2 : 3. Lapangan umum lebih kecil dari lapangan istana, tetapi lebih besar dari ukuran ruangan.","o":["200 cm x 300 cm","36 cm x 54 cm","30 cm x 45 cm","100 cm x 150 cm","120 cm x 180 cm"],"s":[0,0,0,0,1],"w":["Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “120 cm x 180 cm”, bukan “200 cm x 300 cm”. “200 cm x 300 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “200 cm x 300 cm untuk penggunaan di lapangan istana kepresidenan”","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “120 cm x 180 cm”, bukan “36 cm x 54 cm”. “36 cm x 54 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “36 cm x 54 cm untuk penggunaan di mobil Presiden dan Wakil Presiden”","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “120 cm x 180 cm”, bukan “30 cm x 45 cm”. “30 cm x 45 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “30 cm x 45 cm untuk penggunaan di mobil pejabat negara”","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “120 cm x 180 cm”, bukan “100 cm x 150 cm”.","Benar. Ini sesuai Pasal 4 UU Nomor 24 Tahun 2009."],"h":"Semua ukuran resmi berbanding 2 : 3. Lapangan umum lebih kecil dari lapangan istana, tetapi lebih besar dari ukuran ruangan."},{"i":2879,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Menurut UU Nomor 24 Tahun 2009, ukuran Bendera Negara untuk penggunaan di ruangan adalah …","e":"Pasal 4 UU Nomor 24 Tahun 2009 menyebut: “Bendera Negara sebagaimana dimaksud pada ayat (1) dibuat dengan ketentuan ukuran: 100 cm x 150 cm untuk penggunaan di ruangan”\nCara cepat: Ukuran untuk ruangan sama dengan ukuran untuk kapal dan kereta api.","o":["100 cm x 150 cm","120 cm x 180 cm","20 cm x 30 cm","200 cm x 300 cm","36 cm x 54 cm"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 4 UU Nomor 24 Tahun 2009.","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “100 cm x 150 cm”, bukan “120 cm x 180 cm”. “120 cm x 180 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “120 cm x 180 cm untuk penggunaan di lapangan umum”","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “100 cm x 150 cm”, bukan “20 cm x 30 cm”. “20 cm x 30 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “20 cm x 30 cm untuk penggunaan di kendaraan umum”","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “100 cm x 150 cm”, bukan “200 cm x 300 cm”. “200 cm x 300 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “200 cm x 300 cm untuk penggunaan di lapangan istana kepresidenan”","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “100 cm x 150 cm”, bukan “36 cm x 54 cm”. “36 cm x 54 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “36 cm x 54 cm untuk penggunaan di mobil Presiden dan Wakil Presiden”"],"h":"Ukuran untuk ruangan sama dengan ukuran untuk kapal dan kereta api."},{"i":2880,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":4,"q":"Menurut UU Nomor 24 Tahun 2009, ukuran Bendera Negara untuk mobil Presiden dan Wakil Presiden adalah …","e":"Pasal 4 UU Nomor 24 Tahun 2009 menyebut: “Bendera Negara sebagaimana dimaksud pada ayat (1) dibuat dengan ketentuan ukuran: 36 cm x 54 cm untuk penggunaan di mobil Presiden dan Wakil Presiden”\nCara cepat: Bendera mobil Presiden sedikit lebih besar daripada bendera mobil pejabat negara; keduanya berbanding 2 : 3.","o":["100 cm x 150 cm","20 cm x 30 cm","36 cm x 54 cm","10 cm x 15 cm","30 cm x 45 cm"],"s":[0,0,1,0,0],"w":["Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “36 cm x 54 cm”, bukan “100 cm x 150 cm”.","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “36 cm x 54 cm”, bukan “20 cm x 30 cm”. “20 cm x 30 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “20 cm x 30 cm untuk penggunaan di kendaraan umum”","Benar. Ini sesuai Pasal 4 UU Nomor 24 Tahun 2009.","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “36 cm x 54 cm”, bukan “10 cm x 15 cm”. “10 cm x 15 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “10 cm x 15 cm untuk penggunaan di meja”","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “36 cm x 54 cm”, bukan “30 cm x 45 cm”. “30 cm x 45 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “30 cm x 45 cm untuk penggunaan di mobil pejabat negara”"],"h":"Bendera mobil Presiden sedikit lebih besar daripada bendera mobil pejabat negara; keduanya berbanding 2 : 3."},{"i":2881,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":2,"q":"Menurut UU Nomor 24 Tahun 2009, ukuran Bendera Negara untuk lapangan istana kepresidenan adalah …","e":"Pasal 4 UU Nomor 24 Tahun 2009 menyebut: “Bendera Negara sebagaimana dimaksud pada ayat (1) dibuat dengan ketentuan ukuran: 200 cm x 300 cm untuk penggunaan di lapangan istana kepresidenan”\nCara cepat: Istana kepresidenan memakai ukuran terbesar yang diatur undang-undang ini.","o":["250 cm x 375 cm","120 cm x 180 cm","150 cm x 225 cm","100 cm x 150 cm","200 cm x 300 cm"],"s":[0,0,0,0,1],"w":["Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “200 cm x 300 cm”, bukan “250 cm x 375 cm”.","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “200 cm x 300 cm”, bukan “120 cm x 180 cm”. “120 cm x 180 cm” ada di ketentuan lain, Pasal 4 UU Nomor 24 Tahun 2009: “120 cm x 180 cm untuk penggunaan di lapangan umum”","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “200 cm x 300 cm”, bukan “150 cm x 225 cm”.","Menurut Pasal 4 UU Nomor 24 Tahun 2009, jawabannya “200 cm x 300 cm”, bukan “100 cm x 150 cm”.","Benar. Ini sesuai Pasal 4 UU Nomor 24 Tahun 2009."],"h":"Istana kepresidenan memakai ukuran terbesar yang diatur undang-undang ini."},{"i":2882,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":2,"q":"Menurut UU Nomor 24 Tahun 2009, Bendera Pusaka Sang Saka Merah Putih disimpan dan dipelihara di …","e":"Pasal 5 UU Nomor 24 Tahun 2009 menyebut: “Bendera Pusaka Sang Saka Merah Putih disimpan dan dipelihara di Monumen Nasional Jakarta.”\nBendera Pusaka adalah bendera yang dikibarkan saat Proklamasi 17 Agustus 1945 di Jalan Pegangsaan Timur Nomor 56 Jakarta.\nCara cepat: Simbol kemerdekaan disimpan di monumen nasional yang menjadi ikon ibu kota (Monas).","o":["Gedung Joang '45 Jakarta","Arsip Nasional Republik Indonesia","Museum Nasional Jakarta","Museum Perumusan Naskah Proklamasi","Monumen Nasional Jakarta"],"s":[0,0,0,0,1],"w":["Menurut Pasal 5 UU Nomor 24 Tahun 2009, jawabannya “Monumen Nasional Jakarta”, bukan “Gedung Joang '45 Jakarta”.","Menurut Pasal 5 UU Nomor 24 Tahun 2009, jawabannya “Monumen Nasional Jakarta”, bukan “Arsip Nasional Republik Indonesia”.","Menurut Pasal 5 UU Nomor 24 Tahun 2009, jawabannya “Monumen Nasional Jakarta”, bukan “Museum Nasional Jakarta”.","Menurut Pasal 5 UU Nomor 24 Tahun 2009, jawabannya “Monumen Nasional Jakarta”, bukan “Museum Perumusan Naskah Proklamasi”.","Benar. Ini sesuai Pasal 5 UU Nomor 24 Tahun 2009."],"h":"Simbol kemerdekaan disimpan di monumen nasional yang menjadi ikon ibu kota (Monas)."},{"i":2883,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":1,"q":"Bendera Negara yang dikibarkan pada Proklamasi Kemerdekaan 17 Agustus 1945 di Jalan Pegangsaan Timur Nomor 56 Jakarta disebut …","e":"Pasal 5 UU Nomor 24 Tahun 2009 menyebut: “Bendera Negara yang dikibarkan pada Proklamasi Kemerdekaan Bangsa Indonesia tanggal 17 Agustus 1945 di Jalan Pegangsaan Timur Nomor 56 Jakarta disebut Bendera Pusaka Sang Saka Merah Putih.”\nBendera itu disimpan dan dipelihara di Monumen Nasional Jakarta (Pasal 5 ayat 2).\nCara cepat: Kata 'pusaka' dipakai untuk benda bersejarah yang diwariskan.","o":["Bendera Kebangsaan Sang Dwiwarna","Bendera Duplikat Merah Putih","Bendera Proklamasi Sang Merah Putih","Bendera Pusaka Sang Saka Merah Putih","Panji Merah Putih"],"s":[0,0,0,1,0],"w":["Menurut Pasal 5 UU Nomor 24 Tahun 2009, jawabannya “Bendera Pusaka Sang Saka Merah Putih”, bukan “Bendera Kebangsaan Sang Dwiwarna”.","Menurut Pasal 5 UU Nomor 24 Tahun 2009, jawabannya “Bendera Pusaka Sang Saka Merah Putih”, bukan “Bendera Duplikat Merah Putih”.","Menurut Pasal 5 UU Nomor 24 Tahun 2009, jawabannya “Bendera Pusaka Sang Saka Merah Putih”, bukan “Bendera Proklamasi Sang Merah Putih”.","Benar. Ini sesuai Pasal 5 UU Nomor 24 Tahun 2009.","Menurut Pasal 5 UU Nomor 24 Tahun 2009, jawabannya “Bendera Pusaka Sang Saka Merah Putih”, bukan “Panji Merah Putih”."],"h":"Kata 'pusaka' dipakai untuk benda bersejarah yang diwariskan."},{"i":2884,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":1,"q":"Pengibaran dan/atau pemasangan Bendera Negara dilakukan pada waktu antara …","e":"Pasal 7 UU Nomor 24 Tahun 2009 menyebut: “Pengibaran dan/atau pemasangan Bendera Negara sebagaimana dimaksud dalam Pasal 6 dilakukan pada waktu antara matahari terbit hingga matahari terbenam.”\nDalam keadaan tertentu, pengibaran dapat dilakukan pada malam hari (Pasal 7 ayat 2).\nCara cepat: Undang-undang memakai patokan alam, bukan jam.","o":["pagi hingga malam hari","pukul 07.00 hingga pukul 17.00","matahari terbit hingga tengah hari","pukul 06.00 hingga pukul 18.00","matahari terbit hingga matahari terbenam"],"s":[0,0,0,0,1],"w":["Menurut Pasal 7 UU Nomor 24 Tahun 2009, jawabannya “matahari terbit hingga matahari terbenam”, bukan “pagi hingga malam hari”.","Menurut Pasal 7 UU Nomor 24 Tahun 2009, jawabannya “matahari terbit hingga matahari terbenam”, bukan “pukul 07.00 hingga pukul 17.00”.","Menurut Pasal 7 UU Nomor 24 Tahun 2009, jawabannya “matahari terbit hingga matahari terbenam”, bukan “matahari terbit hingga tengah hari”.","Menurut Pasal 7 UU Nomor 24 Tahun 2009, jawabannya “matahari terbit hingga matahari terbenam”, bukan “pukul 06.00 hingga pukul 18.00”.","Benar. Ini sesuai Pasal 7 UU Nomor 24 Tahun 2009."],"h":"Undang-undang memakai patokan alam, bukan jam."},{"i":2885,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Menurut UU Nomor 24 Tahun 2009, Bendera Negara dapat digunakan sebagai tanda perdamaian apabila terjadi …","e":"Pasal 12 UU Nomor 24 Tahun 2009 menyebut: “Bendera Negara sebagai tanda perdamaian sebagaimana dimaksud pada ayat (1) huruf a digunakan apabila terjadi konflik horizontal di wilayah Negara Kesatuan Republik Indonesia.”\nBendera Negara juga dapat dipakai sebagai tanda berkabung dan penutup peti atau usungan jenazah (Pasal 12 ayat 1).\nCara cepat: Tanda perdamaian dipakai saat sesama warga bertikai; setiap pihak yang bertikai wajib menghentikan pertikaian.","o":["pergantian kepala negara","konflik horizontal di wilayah NKRI","perang dengan negara lain","bencana alam nasional","sengketa hasil pemilihan umum"],"s":[0,1,0,0,0],"w":["Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “konflik horizontal di wilayah NKRI”, bukan “pergantian kepala negara”.","Benar. Ini sesuai Pasal 12 UU Nomor 24 Tahun 2009.","Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “konflik horizontal di wilayah NKRI”, bukan “perang dengan negara lain”.","Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “konflik horizontal di wilayah NKRI”, bukan “bencana alam nasional”.","Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “konflik horizontal di wilayah NKRI”, bukan “sengketa hasil pemilihan umum”."],"h":"Tanda perdamaian dipakai saat sesama warga bertikai; setiap pihak yang bertikai wajib menghentikan pertikaian."},{"i":2886,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Apabila Presiden atau Wakil Presiden meninggal dunia, Bendera Negara dikibarkan setengah tiang selama …","e":"Pasal 12 UU Nomor 24 Tahun 2009 menyebut: “Bendera Negara digunakan sebagai tanda berkabung sebagaimana dimaksud pada ayat (1) huruf b apabila Presiden atau Wakil Presiden, mantan Presiden atau mantan Wakil Presiden, pimpinan atau anggota lembaga negara, menteri atau pejabat setingkat menteri, kepala daerah, dan/atau pimpinan dewan perwakilan rakyat daerah meninggal dunia. Apabila Presiden atau Wakil Presiden sebagaimana dimaksud pada ayat (4) meninggal dunia, pengibaran Bendera Negara setengah tiang dilakukan selama tiga hari berturut-turut di seluruh wilayah Negara Kesatuan Republik Indonesia dan semua kantor perwakilan Republik Indonesia di luar negeri.”\nPengibaran setengah tiang itu berlaku di seluruh wilayah NKRI dan semua kantor perwakilan RI di luar negeri.\nCara cepat: Presiden atau Wakil Presiden wafat: tiga hari di seluruh negeri. Pimpinan lembaga negara atau menteri: dua hari, terbatas di kantor terkait.","o":["dua hari berturut-turut","tujuh hari berturut-turut","satu hari","tiga hari berturut-turut","empat puluh hari"],"s":[0,0,0,1,0],"w":["Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “tiga hari berturut-turut”, bukan “dua hari berturut-turut”. “dua hari berturut-turut” ada di ketentuan lain, Pasal 12 UU Nomor 24 Tahun 2009: “…meninggal dunia, pengibaran Bendera Negara setengah tiang dilakukan selama dua hari berturut-turut terbatas pada gedung atau kantor pejabat negara yang bersangkutan”","Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “tiga hari berturut-turut”, bukan “tujuh hari berturut-turut”.","Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “tiga hari berturut-turut”, bukan “satu hari”. “satu hari” ada di ketentuan lain, Pasal 12 UU Nomor 24 Tahun 2009: “…meninggal dunia, pengibaran Bendera Negara setengah tiang dilakukan selama satu hari, terbatas pada gedung atau kantor pejabat yang bersangkutan”","Benar. Ini sesuai Pasal 12 UU Nomor 24 Tahun 2009.","Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “tiga hari berturut-turut”, bukan “empat puluh hari”."],"h":"Presiden atau Wakil Presiden wafat: tiga hari di seluruh negeri. Pimpinan lembaga negara atau menteri: dua hari, terbatas di kantor terkait."},{"i":2887,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":4,"q":"Apabila pimpinan lembaga negara atau menteri meninggal dunia, Bendera Negara dikibarkan setengah tiang selama …","e":"Pasal 12 UU Nomor 24 Tahun 2009 menyebut: “Apabila pimpinan lembaga negara dan menteri atau pejabat setingkat menteri sebagaimana dimaksud pada ayat (4) meninggal dunia, pengibaran Bendera Negara setengah tiang dilakukan selama dua hari berturut-turut terbatas pada gedung atau kantor pejabat negara yang bersangkutan.”\nPengibarannya terbatas pada gedung atau kantor pejabat negara yang bersangkutan.\nCara cepat: Presiden atau Wakil Presiden wafat: tiga hari di seluruh negeri. Pimpinan lembaga negara atau menteri: satu hari lebih singkat.","o":["satu minggu","satu hari","tujuh hari berturut-turut","tiga hari berturut-turut","dua hari berturut-turut"],"s":[0,0,0,0,1],"w":["Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “dua hari berturut-turut”, bukan “satu minggu”.","Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “dua hari berturut-turut”, bukan “satu hari”. “satu hari” ada di ketentuan lain, Pasal 12 UU Nomor 24 Tahun 2009: “…meninggal dunia, pengibaran Bendera Negara setengah tiang dilakukan selama satu hari, terbatas pada gedung atau kantor pejabat yang bersangkutan”","Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “dua hari berturut-turut”, bukan “tujuh hari berturut-turut”.","Menurut Pasal 12 UU Nomor 24 Tahun 2009, jawabannya “dua hari berturut-turut”, bukan “tiga hari berturut-turut”. “tiga hari berturut-turut” ada di ketentuan lain, Pasal 12 UU Nomor 24 Tahun 2009: “…meninggal dunia, pengibaran Bendera Negara setengah tiang dilakukan selama tiga hari berturut-turut di seluruh wilayah Negara Kesatuan Republik Indonesia dan semua kantor…”","Benar. Ini sesuai Pasal 12 UU Nomor 24 Tahun 2009."],"h":"Presiden atau Wakil Presiden wafat: tiga hari di seluruh negeri. Pimpinan lembaga negara atau menteri: satu hari lebih singkat."},{"i":2888,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":2,"q":"Setiap orang dilarang melakukan hal-hal berikut terhadap Bendera Negara, kecuali …","e":"Pasal 24 UU Nomor 24 Tahun 2009: Setiap orang dilarang: merusak, merobek, menginjak-injak, membakar, atau melakukan perbuatan lain dengan maksud menodai, menghina, atau merendahkan kehormatan Bendera Negara; memakai Bendera Negara untuk reklame atau iklan komersial; mengibarkan Bendera Negara yang rusak, robek, luntur, kusut, atau kusam; mencetak, menyulam, dan menulis huruf, angka, gambar atau tanda lain dan memasang lencana atau benda apapun pada Bendera Negara;; memakai Bendera Negara untuk langit-langit, atap, pembungkus barang, dan tutup barang yang dapat menurunkan kehormatan Bendera Negara.\n“mengibarkannya pada peringatan Hari Kemerdekaan 17 Agustus” tidak termasuk di dalamnya.\nJustru sebaliknya, Bendera Negara wajib dikibarkan pada setiap peringatan Hari Kemerdekaan 17 Agustus (Pasal 7 ayat 3).\nCara cepat: Larangan terhadap bendera intinya dua: jangan merendahkan kehormatannya (iklan, atap, pembungkus, dicoret) dan jangan mengibarkan bendera yang rusak.","o":["mengibarkannya pada peringatan Hari Kemerdekaan 17 Agustus","mengibarkan Bendera Negara yang rusak, robek, luntur, kusut, atau kusam","memakai Bendera Negara untuk reklame atau iklan komersial","memakai Bendera Negara untuk langit-langit, atap, pembungkus barang","mencetak, menyulam, dan menulis huruf, angka, gambar atau tanda lain"],"s":[1,0,0,0,0],"w":["Benar. Ini tidak termasuk dalam Pasal 24 UU Nomor 24 Tahun 2009.","Ini disebut dalam Pasal 24 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Ini disebut dalam Pasal 24 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Ini disebut dalam Pasal 24 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Ini disebut dalam Pasal 24 UU Nomor 24 Tahun 2009, jadi bukan jawabannya."],"h":"Larangan terhadap bendera intinya dua: jangan merendahkan kehormatannya (iklan, atap, pembungkus, dicoret) dan jangan mengibarkan bendera yang rusak."},{"i":2889,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Bendera Negara wajib dikibarkan setiap hari di tempat-tempat berikut, kecuali …","e":"Pasal 9 UU Nomor 24 Tahun 2009: Bendera Negara sebagaimana dimaksud dalam Pasal 4 ayat (1) wajib dikibarkan setiap hari di: istana Presiden dan Wakil Presiden; gedung atau kantor lembaga negara; gedung atau kantor lembaga pemerintah; gedung atau kantor lembaga pemerintah nonkementerian; gedung atau kantor lembaga pemerintah daerah; gedung atau kantor dewan perwakilan rakyat daerah; gedung atau kantor perwakilan Republik Indonesia di luar negeri; gedung atau halaman satuan pendidikan; gedung atau kantor swasta; rumah jabatan Presiden dan Wakil Presiden; rumah jabatan pimpinan lembaga negara; rumah jabatan menteri; rumah jabatan pimpinan lembaga pemerintahan nonkementerian; rumah jabatan gubernur, bupati, walikota, dan camat; gedung atau kantor atau rumah jabatan lain; pos perbatasan dan pulau-pulau terluar di wilayah Negara Kesatuan Republik Indonesia; lingkungan Tentara Nasional Indonesia dan Kepolisian Republik Indonesia;; taman makam pahlawan nasional; Penggunaan Bendera Negara di lingkungan Tentara Nasional Indonesia dan Kepolisian Republik Indonesia sebagaimana dimaksud pada ayat (1) huruf q diatur tersendiri oleh pimpinan institusi dengan berpedoman pada Undang-Undang ini; Penggunaan Bendera Negara di kantor perwakilan negara Republik Indonesia di luar negeri sebagaimana dimaksud pada ayat (1) huruf g dilakukan dengan berpedoman pada Undang-Undang ini; Dalam hal Bendera Negara sebagaimana dimaksud pada ayat (1) huruf g digunakan di luar gedung atau kantor perwakilan Republik Indonesia di luar negeri dilakukan sesuai dengan peraturan penggunaan bendera asing yang berlaku di negara yang bersangkutan.\n“rumah pribadi setiap warga negara” tidak termasuk di dalamnya.\nWarga negara wajib mengibarkan Bendera Negara di rumah pada setiap peringatan Hari Kemerdekaan 17 Agustus (Pasal 7 ayat 3).\nCara cepat: Kewajiban harian berlaku untuk kantor, gedung sekolah, rumah jabatan, dan pos perbatasan. Rumah warga cukup pada hari kemerdekaan.","o":["pos perbatasan dan pulau-pulau terluar","istana Presiden dan Wakil Presiden","rumah pribadi setiap warga negara","gedung atau halaman satuan pendidikan","gedung atau kantor swasta"],"s":[0,0,1,0,0],"w":["Ini disebut dalam Pasal 9 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Ini disebut dalam Pasal 9 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Benar. Ini tidak termasuk dalam Pasal 9 UU Nomor 24 Tahun 2009.","Ini disebut dalam Pasal 9 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Ini disebut dalam Pasal 9 UU Nomor 24 Tahun 2009, jadi bukan jawabannya."],"h":"Kewajiban harian berlaku untuk kantor, gedung sekolah, rumah jabatan, dan pos perbatasan. Rumah warga cukup pada hari kemerdekaan."},{"i":2890,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":1,"q":"Bendera Negara dinaikkan atau diturunkan pada tiang secara perlahan-lahan, dengan khidmat, dan …","e":"Pasal 14 UU Nomor 24 Tahun 2009 menyebut: “Bendera Negara dinaikkan atau diturunkan pada tiang secara perlahan-lahan, dengan khidmat, dan tidak menyentuh tanah.”\nCara cepat: Semua tata cara bendera bertujuan menjaga kehormatannya.","o":["diiringi bunyi sirene","dihentikan di tengah tiang","dipegang oleh tiga orang petugas","diiringi tepuk tangan","tidak menyentuh tanah"],"s":[0,0,0,0,1],"w":["Menurut Pasal 14 UU Nomor 24 Tahun 2009, jawabannya “tidak menyentuh tanah”, bukan “diiringi bunyi sirene”.","Menurut Pasal 14 UU Nomor 24 Tahun 2009, jawabannya “tidak menyentuh tanah”, bukan “dihentikan di tengah tiang”.","Menurut Pasal 14 UU Nomor 24 Tahun 2009, jawabannya “tidak menyentuh tanah”, bukan “dipegang oleh tiga orang petugas”.","Menurut Pasal 14 UU Nomor 24 Tahun 2009, jawabannya “tidak menyentuh tanah”, bukan “diiringi tepuk tangan”.","Benar. Ini sesuai Pasal 14 UU Nomor 24 Tahun 2009."],"h":"Semua tata cara bendera bertujuan menjaga kehormatannya."},{"i":2891,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Bendera Negara yang akan dikibarkan setengah tiang …","e":"Pasal 14 UU Nomor 24 Tahun 2009 menyebut: “Bendera Negara yang dikibarkan setengah tiang, dinaikkan hingga ke ujung tiang, dihentikan sebentar dan diturunkan tepat setengah tiang.”\nSaat hendak diturunkan, bendera setengah tiang juga dinaikkan dulu hingga ujung tiang (Pasal 14 ayat 3).\nCara cepat: Bendera selalu 'menyentuh puncak' dulu sebagai penghormatan, baru turun ke posisi setengah tiang.","o":["dinaikkan ke ujung tiang lalu dibiarkan di sana","dipasang setengah tiang tanpa upacara","dinaikkan hingga ke ujung tiang, dihentikan sebentar, lalu diturunkan tepat setengah tiang","langsung dinaikkan sampai setengah tiang","dinaikkan setengah tiang lalu dibiarkan sampai sore"],"s":[0,0,1,0,0],"w":["Menurut Pasal 14 UU Nomor 24 Tahun 2009, jawabannya “dinaikkan hingga ke ujung tiang, dihentikan sebentar, lalu diturunkan tepat setengah tiang”, bukan “dinaikkan ke ujung tiang lalu dibiarkan di sana”.","Menurut Pasal 14 UU Nomor 24 Tahun 2009, jawabannya “dinaikkan hingga ke ujung tiang, dihentikan sebentar, lalu diturunkan tepat setengah tiang”, bukan “dipasang setengah tiang tanpa upacara”.","Benar. Ini sesuai Pasal 14 UU Nomor 24 Tahun 2009.","Menurut Pasal 14 UU Nomor 24 Tahun 2009, jawabannya “dinaikkan hingga ke ujung tiang, dihentikan sebentar, lalu diturunkan tepat setengah tiang”, bukan “langsung dinaikkan sampai setengah tiang”.","Menurut Pasal 14 UU Nomor 24 Tahun 2009, jawabannya “dinaikkan hingga ke ujung tiang, dihentikan sebentar, lalu diturunkan tepat setengah tiang”, bukan “dinaikkan setengah tiang lalu dibiarkan sampai sore”."],"h":"Bendera selalu 'menyentuh puncak' dulu sebagai penghormatan, baru turun ke posisi setengah tiang."},{"i":2892,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":1,"q":"Menurut UU Nomor 24 Tahun 2009, Bahasa Indonesia bersumber dari bahasa yang diikrarkan dalam …","e":"Pasal 25 UU Nomor 24 Tahun 2009 menyebut: “Bahasa Indonesia yang dinyatakan sebagai bahasa resmi negara dalam Pasal 36 Undang-Undang Dasar Negara Kesatuan Republik Indonesia Tahun 1945 bersumber dari bahasa yang diikrarkan dalam Sumpah Pemuda tanggal 28 Oktober 1928 sebagai bahasa persatuan yang dikembangkan sesuai dengan dinamika peradaban bangsa.”\nBahasa Indonesia dinyatakan sebagai bahasa resmi negara dalam Pasal 36 UUD 1945.\nCara cepat: Kata kuncinya 'diikrarkan': ikrar ketiga para pemuda menjunjung bahasa persatuan.","o":["Kongres Bahasa Indonesia I tahun 1938","Sidang PPKI 18 Agustus 1945","Kebangkitan Nasional 20 Mei 1908","Proklamasi Kemerdekaan 17 Agustus 1945","Sumpah Pemuda tanggal 28 Oktober 1928"],"s":[0,0,0,0,1],"w":["Menurut Pasal 25 UU Nomor 24 Tahun 2009, jawabannya “Sumpah Pemuda tanggal 28 Oktober 1928”, bukan “Kongres Bahasa Indonesia I tahun 1938”.","Menurut Pasal 25 UU Nomor 24 Tahun 2009, jawabannya “Sumpah Pemuda tanggal 28 Oktober 1928”, bukan “Sidang PPKI 18 Agustus 1945”.","Menurut Pasal 25 UU Nomor 24 Tahun 2009, jawabannya “Sumpah Pemuda tanggal 28 Oktober 1928”, bukan “Kebangkitan Nasional 20 Mei 1908”.","Menurut Pasal 25 UU Nomor 24 Tahun 2009, jawabannya “Sumpah Pemuda tanggal 28 Oktober 1928”, bukan “Proklamasi Kemerdekaan 17 Agustus 1945”.","Benar. Ini sesuai Pasal 25 UU Nomor 24 Tahun 2009."],"h":"Kata kuncinya 'diikrarkan': ikrar ketiga para pemuda menjunjung bahasa persatuan."},{"i":2893,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Fungsi Bahasa Indonesia menurut Pasal 25 ayat (2) UU Nomor 24 Tahun 2009 adalah sebagai berikut, kecuali …","e":"Pasal 25 UU Nomor 24 Tahun 2009: Bahasa Indonesia sebagaimana dimaksud pada ayat (1) berfungsi sebagai jati diri bangsa, kebanggaan nasional, sarana pemersatu berbagai suku bangsa, serta sarana komunikasi antardaerah dan antarbudaya daerah.\n“pengganti bahasa daerah dalam kehidupan sehari-hari” tidak termasuk di dalamnya.\nPemerintah daerah wajib mengembangkan, membina, dan melindungi bahasa dan sastra daerah (Pasal 42).\nCara cepat: Bahasa Indonesia mempersatukan, tetapi tidak menggantikan bahasa daerah; negara justru memelihara bahasa daerah (UUD Pasal 32 ayat 2).","o":["sarana komunikasi antardaerah dan antarbudaya daerah","pengganti bahasa daerah dalam kehidupan sehari-hari","jati diri bangsa","kebanggaan nasional","sarana pemersatu berbagai suku bangsa"],"s":[0,1,0,0,0],"w":["Ini disebut dalam Pasal 25 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Benar. Ini tidak termasuk dalam Pasal 25 UU Nomor 24 Tahun 2009.","Ini disebut dalam Pasal 25 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Ini disebut dalam Pasal 25 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Ini disebut dalam Pasal 25 UU Nomor 24 Tahun 2009, jadi bukan jawabannya."],"h":"Bahasa Indonesia mempersatukan, tetapi tidak menggantikan bahasa daerah; negara justru memelihara bahasa daerah (UUD Pasal 32 ayat 2)."},{"i":2894,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Penggunaan Bahasa Indonesia sebagai bahasa pengantar pendidikan nasional tidak berlaku untuk …","e":"Pasal 29 UU Nomor 24 Tahun 2009 menyebut: “Penggunaan Bahasa Indonesia sebagaimana dimaksud pada ayat (1) tidak berlaku untuk satuan pendidikan asing atau satuan pendidikan khusus yang mendidik warga negara asing.”\nBahasa asing tetap boleh dipakai sebagai bahasa pengantar untuk mendukung kemampuan berbahasa asing peserta didik (Pasal 29 ayat 2).\nCara cepat: Pengecualiannya hanya untuk lembaga berstatus asing atau yang muridnya warga negara asing.","o":["sekolah dasar di daerah terpencil","sekolah inklusi","satuan pendidikan asing atau satuan pendidikan khusus yang mendidik warga negara asing","perguruan tinggi negeri","pondok pesantren"],"s":[0,0,1,0,0],"w":["Menurut Pasal 29 UU Nomor 24 Tahun 2009, jawabannya “satuan pendidikan asing atau satuan pendidikan khusus yang mendidik warga negara asing”, bukan “sekolah dasar di daerah terpencil”.","Menurut Pasal 29 UU Nomor 24 Tahun 2009, jawabannya “satuan pendidikan asing atau satuan pendidikan khusus yang mendidik warga negara asing”, bukan “sekolah inklusi”.","Benar. Ini sesuai Pasal 29 UU Nomor 24 Tahun 2009.","Menurut Pasal 29 UU Nomor 24 Tahun 2009, jawabannya “satuan pendidikan asing atau satuan pendidikan khusus yang mendidik warga negara asing”, bukan “perguruan tinggi negeri”.","Menurut Pasal 29 UU Nomor 24 Tahun 2009, jawabannya “satuan pendidikan asing atau satuan pendidikan khusus yang mendidik warga negara asing”, bukan “pondok pesantren”."],"h":"Pengecualiannya hanya untuk lembaga berstatus asing atau yang muridnya warga negara asing."},{"i":2895,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Nota kesepahaman atau perjanjian yang melibatkan pihak asing wajib berbahasa Indonesia dan ditulis juga dalam …","e":"Pasal 31 UU Nomor 24 Tahun 2009 menyebut: “Nota kesepahaman atau perjanjian sebagaimana dimaksud pada ayat (1) yang melibatkan pihak asing ditulis juga dalam bahasa nasional pihak asing tersebut dan/atau bahasa Inggris.”\nCara cepat: Bahasa Indonesia tetap wajib; tambahannya bahasa yang dipahami mitra asing.","o":["bahasa yang dipilih notaris","bahasa nasional pihak asing tersebut dan/atau bahasa Inggris","bahasa resmi PBB saja","bahasa Latin","bahasa daerah tempat perjanjian dibuat"],"s":[0,1,0,0,0],"w":["Menurut Pasal 31 UU Nomor 24 Tahun 2009, jawabannya “bahasa nasional pihak asing tersebut dan/atau bahasa Inggris”, bukan “bahasa yang dipilih notaris”.","Benar. Ini sesuai Pasal 31 UU Nomor 24 Tahun 2009.","Menurut Pasal 31 UU Nomor 24 Tahun 2009, jawabannya “bahasa nasional pihak asing tersebut dan/atau bahasa Inggris”, bukan “bahasa resmi PBB saja”.","Menurut Pasal 31 UU Nomor 24 Tahun 2009, jawabannya “bahasa nasional pihak asing tersebut dan/atau bahasa Inggris”, bukan “bahasa Latin”.","Menurut Pasal 31 UU Nomor 24 Tahun 2009, jawabannya “bahasa nasional pihak asing tersebut dan/atau bahasa Inggris”, bukan “bahasa daerah tempat perjanjian dibuat”."],"h":"Bahasa Indonesia tetap wajib; tambahannya bahasa yang dipahami mitra asing."},{"i":2896,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":4,"q":"Menurut UU Nomor 24 Tahun 2009, pernyataan yang tepat tentang penggunaan Bahasa Indonesia dalam forum adalah …","e":"Pasal 32 UU Nomor 24 Tahun 2009 menyebut: “Bahasa Indonesia wajib digunakan dalam forum yang bersifat nasional atau forum yang bersifat internasional di Indonesia. Bahasa Indonesia dapat digunakan dalam forum yang bersifat internasional di luar negeri.”\nCara cepat: Di dalam negeri wajib, di luar negeri boleh.","o":["tidak diatur; setiap penyelenggara bebas memilih bahasa","dapat digunakan di forum nasional dan wajib di forum internasional","hanya wajib di forum nasional; forum internasional memakai bahasa Inggris","wajib di semua forum, baik di dalam maupun di luar negeri","wajib di forum nasional dan forum internasional di Indonesia, serta dapat digunakan di forum internasional di luar negeri"],"s":[0,0,0,0,1],"w":["Menurut Pasal 32 UU Nomor 24 Tahun 2009, jawabannya “wajib di forum nasional dan forum internasional di Indonesia, serta dapat digunakan di forum internasional di luar negeri”, bukan “tidak diatur; setiap penyelenggara bebas memilih bahasa”.","Menurut Pasal 32 UU Nomor 24 Tahun 2009, jawabannya “wajib di forum nasional dan forum internasional di Indonesia, serta dapat digunakan di forum internasional di luar negeri”, bukan “dapat digunakan di forum nasional dan wajib di forum internasional”.","Menurut Pasal 32 UU Nomor 24 Tahun 2009, jawabannya “wajib di forum nasional dan forum internasional di Indonesia, serta dapat digunakan di forum internasional di luar negeri”, bukan “hanya wajib di forum nasional; forum internasional memakai bahasa Inggris”.","Menurut Pasal 32 UU Nomor 24 Tahun 2009, jawabannya “wajib di forum nasional dan forum internasional di Indonesia, serta dapat digunakan di forum internasional di luar negeri”, bukan “wajib di semua forum, baik di dalam maupun di luar negeri”.","Benar. Ini sesuai Pasal 32 UU Nomor 24 Tahun 2009."],"h":"Di dalam negeri wajib, di luar negeri boleh."},{"i":2897,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Pegawai di lingkungan kerja pemerintah dan swasta yang belum mampu berbahasa Indonesia wajib …","e":"Pasal 33 UU Nomor 24 Tahun 2009 menyebut: “Pegawai di lingkungan kerja lembaga pemerintah dan swasta sebagaimana dimaksud pada ayat (1) yang belum mampu berbahasa Indonesia wajib mengikuti atau diikutsertakan dalam pembelajaran untuk meraih kemampuan berbahasa Indonesia.”\nBahasa Indonesia wajib digunakan dalam komunikasi resmi di lingkungan kerja pemerintah dan swasta (Pasal 33 ayat 1).\nCara cepat: Undang-undang ini memilih jalan pembinaan, bukan sanksi.","o":["diberhentikan dari pekerjaannya","selalu didampingi penerjemah","mengikuti atau diikutsertakan dalam pembelajaran untuk meraih kemampuan berbahasa Indonesia","memakai bahasa Inggris dalam komunikasi resmi","dipindahkan ke bagian yang tidak melayani publik"],"s":[0,0,1,0,0],"w":["Menurut Pasal 33 UU Nomor 24 Tahun 2009, jawabannya “mengikuti atau diikutsertakan dalam pembelajaran untuk meraih kemampuan berbahasa Indonesia”, bukan “diberhentikan dari pekerjaannya”.","Menurut Pasal 33 UU Nomor 24 Tahun 2009, jawabannya “mengikuti atau diikutsertakan dalam pembelajaran untuk meraih kemampuan berbahasa Indonesia”, bukan “selalu didampingi penerjemah”.","Benar. Ini sesuai Pasal 33 UU Nomor 24 Tahun 2009.","Menurut Pasal 33 UU Nomor 24 Tahun 2009, jawabannya “mengikuti atau diikutsertakan dalam pembelajaran untuk meraih kemampuan berbahasa Indonesia”, bukan “memakai bahasa Inggris dalam komunikasi resmi”.","Menurut Pasal 33 UU Nomor 24 Tahun 2009, jawabannya “mengikuti atau diikutsertakan dalam pembelajaran untuk meraih kemampuan berbahasa Indonesia”, bukan “dipindahkan ke bagian yang tidak melayani publik”."],"h":"Undang-undang ini memilih jalan pembinaan, bukan sanksi."},{"i":2898,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":2,"q":"Menurut UU Nomor 24 Tahun 2009, nama geografi di Indonesia hanya memiliki … nama resmi.","e":"Pasal 36 UU Nomor 24 Tahun 2009 menyebut: “Nama geografi sebagaimana dimaksud pada ayat (1) hanya memiliki 1 (satu) nama resmi.”\nCara cepat: Satu tempat, satu nama resmi, supaya peta dan dokumen negara tidak membingungkan.","o":["3 (tiga)","2 (dua)","1 (satu)","tidak dibatasi","sesuai jumlah bahasa daerah setempat"],"s":[0,0,1,0,0],"w":["Menurut Pasal 36 UU Nomor 24 Tahun 2009, jawabannya “1 (satu)”, bukan “3 (tiga)”.","Menurut Pasal 36 UU Nomor 24 Tahun 2009, jawabannya “1 (satu)”, bukan “2 (dua)”.","Benar. Ini sesuai Pasal 36 UU Nomor 24 Tahun 2009.","Menurut Pasal 36 UU Nomor 24 Tahun 2009, jawabannya “1 (satu)”, bukan “tidak dibatasi”.","Menurut Pasal 36 UU Nomor 24 Tahun 2009, jawabannya “1 (satu)”, bukan “sesuai jumlah bahasa daerah setempat”."],"h":"Satu tempat, satu nama resmi, supaya peta dan dokumen negara tidak membingungkan."},{"i":2899,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Nama bangunan, jalan, atau lembaga dapat memakai bahasa daerah atau bahasa asing apabila memiliki nilai …","e":"Pasal 36 UU Nomor 24 Tahun 2009 menyebut: “Penamaan sebagaimana dimaksud pada ayat (1) dan ayat (3) dapat menggunakan bahasa daerah atau bahasa asing apabila memiliki nilai sejarah, budaya, adat istiadat, dan/atau keagamaan.”\nPada dasarnya Bahasa Indonesia wajib dipakai untuk nama bangunan, jalan, permukiman, perkantoran, merek dagang, dan lembaga (Pasal 36 ayat 3).\nCara cepat: Pengecualian hanya untuk nilai warisan (sejarah, budaya, adat, agama), bukan pertimbangan bisnis.","o":["estetika modern","promosi pariwisata internasional","investasi asing","sejarah, budaya, adat istiadat, dan/atau keagamaan","komersial dan pemasaran"],"s":[0,0,0,1,0],"w":["Menurut Pasal 36 UU Nomor 24 Tahun 2009, jawabannya “sejarah, budaya, adat istiadat, dan/atau keagamaan”, bukan “estetika modern”.","Menurut Pasal 36 UU Nomor 24 Tahun 2009, jawabannya “sejarah, budaya, adat istiadat, dan/atau keagamaan”, bukan “promosi pariwisata internasional”.","Menurut Pasal 36 UU Nomor 24 Tahun 2009, jawabannya “sejarah, budaya, adat istiadat, dan/atau keagamaan”, bukan “investasi asing”.","Benar. Ini sesuai Pasal 36 UU Nomor 24 Tahun 2009.","Menurut Pasal 36 UU Nomor 24 Tahun 2009, jawabannya “sejarah, budaya, adat istiadat, dan/atau keagamaan”, bukan “komersial dan pemasaran”."],"h":"Pengecualian hanya untuk nilai warisan (sejarah, budaya, adat, agama), bukan pertimbangan bisnis."},{"i":2900,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Informasi tentang produk barang atau jasa yang beredar di Indonesia wajib berbahasa Indonesia dan …","e":"Pasal 37 UU Nomor 24 Tahun 2009 menyebut: “Informasi sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan bahasa daerah atau bahasa asing sesuai dengan keperluan.”\nCara cepat: Pola yang sering muncul di UU ini: Bahasa Indonesia wajib, bahasa lain boleh menyertai.","o":["wajib dilengkapi bahasa Inggris","dapat dilengkapi bahasa daerah atau bahasa asing sesuai keperluan","wajib memakai bahasa daerah tempat produk dijual","hanya boleh memakai Bahasa Indonesia","boleh memakai bahasa asing saja untuk produk impor"],"s":[0,1,0,0,0],"w":["Menurut Pasal 37 UU Nomor 24 Tahun 2009, jawabannya “dapat dilengkapi bahasa daerah atau bahasa asing sesuai keperluan”, bukan “wajib dilengkapi bahasa Inggris”.","Benar. Ini sesuai Pasal 37 UU Nomor 24 Tahun 2009.","Menurut Pasal 37 UU Nomor 24 Tahun 2009, jawabannya “dapat dilengkapi bahasa daerah atau bahasa asing sesuai keperluan”, bukan “wajib memakai bahasa daerah tempat produk dijual”.","Menurut Pasal 37 UU Nomor 24 Tahun 2009, jawabannya “dapat dilengkapi bahasa daerah atau bahasa asing sesuai keperluan”, bukan “hanya boleh memakai Bahasa Indonesia”.","Menurut Pasal 37 UU Nomor 24 Tahun 2009, jawabannya “dapat dilengkapi bahasa daerah atau bahasa asing sesuai keperluan”, bukan “boleh memakai bahasa asing saja untuk produk impor”."],"h":"Pola yang sering muncul di UU ini: Bahasa Indonesia wajib, bahasa lain boleh menyertai."},{"i":2901,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":4,"q":"Ketentuan lebih lanjut mengenai penggunaan Bahasa Indonesia (Pasal 26 sampai Pasal 39 UU 24/2009) diatur dalam …","e":"Pasal 40 UU Nomor 24 Tahun 2009 menyebut: “Ketentuan lebih lanjut mengenai penggunaan Bahasa Indonesia sebagaimana dimaksud dalam Pasal 26 sampai dengan Pasal 39 diatur dalam Peraturan Presiden.”\nAturan pelaksananya sekarang Peraturan Presiden Nomor 63 Tahun 2019 tentang Penggunaan Bahasa Indonesia.\nCara cepat: Bedakan: penggunaan Bahasa Indonesia diatur Perpres, sedangkan pengembangan, pembinaan, dan pelindungan bahasa diatur PP (Pasal 41–44).","o":["Peraturan Presiden","Keputusan Presiden","Peraturan Menteri","Peraturan Daerah","Peraturan Pemerintah"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 40 UU Nomor 24 Tahun 2009.","Menurut Pasal 40 UU Nomor 24 Tahun 2009, jawabannya “Peraturan Presiden”, bukan “Keputusan Presiden”.","Menurut Pasal 40 UU Nomor 24 Tahun 2009, jawabannya “Peraturan Presiden”, bukan “Peraturan Menteri”.","Menurut Pasal 40 UU Nomor 24 Tahun 2009, jawabannya “Peraturan Presiden”, bukan “Peraturan Daerah”.","Menurut Pasal 40 UU Nomor 24 Tahun 2009, jawabannya “Peraturan Presiden”, bukan “Peraturan Pemerintah”."],"h":"Bedakan: penggunaan Bahasa Indonesia diatur Perpres, sedangkan pengembangan, pembinaan, dan pelindungan bahasa diatur PP (Pasal 41–44)."},{"i":2902,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Menurut UU Nomor 24 Tahun 2009, yang wajib mengembangkan, membina, dan melindungi bahasa dan sastra daerah adalah …","e":"Pasal 42 UU Nomor 24 Tahun 2009 menyebut: “Pemerintah daerah wajib mengembangkan, membina, dan melindungi bahasa dan sastra daerah agar tetap memenuhi kedudukan dan fungsinya dalam kehidupan bermasyarakat sesuai dengan perkembangan zaman dan agar tetap menjadi bagian dari kekayaan budaya Indonesia.”\nPelaksanaannya di bawah koordinasi lembaga kebahasaan (Pasal 42 ayat 2).\nCara cepat: Bahasa dan sastra Indonesia menjadi kewajiban Pemerintah (Pasal 41); bahasa dan sastra daerah menjadi kewajiban pemerintahan di daerah itu.","o":["Kementerian Luar Negeri","pemerintah daerah","sekolah di daerah tersebut","lembaga adat setempat","masyarakat penutur bahasa itu saja"],"s":[0,1,0,0,0],"w":["Menurut Pasal 42 UU Nomor 24 Tahun 2009, jawabannya “pemerintah daerah”, bukan “Kementerian Luar Negeri”.","Benar. Ini sesuai Pasal 42 UU Nomor 24 Tahun 2009.","Menurut Pasal 42 UU Nomor 24 Tahun 2009, jawabannya “pemerintah daerah”, bukan “sekolah di daerah tersebut”.","Menurut Pasal 42 UU Nomor 24 Tahun 2009, jawabannya “pemerintah daerah”, bukan “lembaga adat setempat”.","Menurut Pasal 42 UU Nomor 24 Tahun 2009, jawabannya “pemerintah daerah”, bukan “masyarakat penutur bahasa itu saja”."],"h":"Bahasa dan sastra Indonesia menjadi kewajiban Pemerintah (Pasal 41); bahasa dan sastra daerah menjadi kewajiban pemerintahan di daerah itu."},{"i":2903,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":2,"q":"Pemerintah meningkatkan fungsi Bahasa Indonesia menjadi … secara bertahap, sistematis, dan berkelanjutan.","e":"Pasal 44 UU Nomor 24 Tahun 2009 menyebut: “Pemerintah meningkatkan fungsi Bahasa Indonesia menjadi bahasa internasional secara bertahap, sistematis, dan berkelanjutan.”\nPeningkatan itu dikoordinasi oleh lembaga kebahasaan (Pasal 44 ayat 2).\nCara cepat: Arah kebijakannya ke luar negeri: dari bahasa nasional naik ke panggung dunia.","o":["bahasa resmi ASEAN","bahasa wajib di seluruh dunia","bahasa ilmu pengetahuan satu-satunya","bahasa internasional","bahasa daerah"],"s":[0,0,0,1,0],"w":["Menurut Pasal 44 UU Nomor 24 Tahun 2009, jawabannya “bahasa internasional”, bukan “bahasa resmi ASEAN”.","Menurut Pasal 44 UU Nomor 24 Tahun 2009, jawabannya “bahasa internasional”, bukan “bahasa wajib di seluruh dunia”.","Menurut Pasal 44 UU Nomor 24 Tahun 2009, jawabannya “bahasa internasional”, bukan “bahasa ilmu pengetahuan satu-satunya”.","Benar. Ini sesuai Pasal 44 UU Nomor 24 Tahun 2009.","Menurut Pasal 44 UU Nomor 24 Tahun 2009, jawabannya “bahasa internasional”, bukan “bahasa daerah”."],"h":"Arah kebijakannya ke luar negeri: dari bahasa nasional naik ke panggung dunia."},{"i":2904,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Menurut UU Nomor 24 Tahun 2009, bendera yang dibuat untuk menunjukkan kedudukan dan kebesaran suatu jabatan atau organisasi disebut …","e":"Pasal 1 UU Nomor 24 Tahun 2009 menyebut: “Panji adalah bendera yang dibuat untuk menunjukkan kedudukan dan kebesaran suatu jabatan atau organisasi.”\nCara cepat: Istilah ini dipakai untuk bendera milik jabatan atau organisasi, misalnya pada satuan dan instansi.","o":["panji","bendera pusaka","spanduk","umbul-umbul","lambang daerah"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 1 UU Nomor 24 Tahun 2009.","Menurut Pasal 1 UU Nomor 24 Tahun 2009, jawabannya “panji”, bukan “bendera pusaka”. “bendera pusaka” ada di ketentuan lain, Pasal 5 UU Nomor 24 Tahun 2009: “…tanggal 17 Agustus 1945 di Jalan Pegangsaan Timur Nomor 56 Jakarta disebut Bendera Pusaka Sang Saka Merah Putih”","Menurut Pasal 1 UU Nomor 24 Tahun 2009, jawabannya “panji”, bukan “spanduk”.","Menurut Pasal 1 UU Nomor 24 Tahun 2009, jawabannya “panji”, bukan “umbul-umbul”.","Menurut Pasal 1 UU Nomor 24 Tahun 2009, jawabannya “panji”, bukan “lambang daerah”."],"h":"Istilah ini dipakai untuk bendera milik jabatan atau organisasi, misalnya pada satuan dan instansi."},{"i":2905,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":1,"q":"Menurut UU Nomor 24 Tahun 2009, bahasa yang digunakan secara turun-temurun oleh warga negara Indonesia di daerah-daerah di wilayah NKRI disebut …","e":"Pasal 1 UU Nomor 24 Tahun 2009 menyebut: “Bahasa daerah adalah bahasa yang digunakan secara turun-temurun oleh warga negara Indonesia di daerah-daerah di wilayah Negara Kesatuan Republik Indonesia.”\nCara cepat: Kata kuncinya 'turun-temurun' dan 'di daerah-daerah'.","o":["bahasa resmi","bahasa nasional","bahasa asing","bahasa daerah","bahasa persatuan"],"s":[0,0,0,1,0],"w":["Menurut Pasal 1 UU Nomor 24 Tahun 2009, jawabannya “bahasa daerah”, bukan “bahasa resmi”.","Menurut Pasal 1 UU Nomor 24 Tahun 2009, jawabannya “bahasa daerah”, bukan “bahasa nasional”. “bahasa nasional” ada di ketentuan lain, Pasal 31 UU Nomor 24 Tahun 2009: “…dimaksud pada ayat (1) yang melibatkan pihak asing ditulis juga dalam bahasa nasional pihak asing tersebut dan/atau bahasa Inggris”","Menurut Pasal 1 UU Nomor 24 Tahun 2009, jawabannya “bahasa daerah”, bukan “bahasa asing”.","Benar. Ini sesuai Pasal 1 UU Nomor 24 Tahun 2009.","Menurut Pasal 1 UU Nomor 24 Tahun 2009, jawabannya “bahasa daerah”, bukan “bahasa persatuan”. “bahasa persatuan” ada di ketentuan lain, Pasal 25 UU Nomor 24 Tahun 2009: “…bahasa yang diikrarkan dalam Sumpah Pemuda tanggal 28 Oktober 1928 sebagai bahasa persatuan yang dikembangkan sesuai dengan dinamika peradaban bangsa”"],"h":"Kata kuncinya 'turun-temurun' dan 'di daerah-daerah'."},{"i":2906,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":1,"q":"Menurut UU Nomor 24 Tahun 2009, Lagu Kebangsaan Indonesia Raya digubah oleh …","e":"Pasal 58 UU Nomor 24 Tahun 2009 menyebut: “Lagu Kebangsaan adalah Indonesia Raya yang digubah oleh Wage Rudolf Supratman.”\nCara cepat: Penggubahnya wartawan sekaligus pemain biola yang memperdengarkan lagu ini pertama kali pada Kongres Pemuda II tahun 1928.","o":["Ismail Marzuki","Cornel Simanjuntak","Kusbini","Wage Rudolf Supratman","Ibu Sud"],"s":[0,0,0,1,0],"w":["Menurut Pasal 58 UU Nomor 24 Tahun 2009, jawabannya “Wage Rudolf Supratman”, bukan “Ismail Marzuki”.","Menurut Pasal 58 UU Nomor 24 Tahun 2009, jawabannya “Wage Rudolf Supratman”, bukan “Cornel Simanjuntak”.","Menurut Pasal 58 UU Nomor 24 Tahun 2009, jawabannya “Wage Rudolf Supratman”, bukan “Kusbini”.","Benar. Ini sesuai Pasal 58 UU Nomor 24 Tahun 2009.","Menurut Pasal 58 UU Nomor 24 Tahun 2009, jawabannya “Wage Rudolf Supratman”, bukan “Ibu Sud”."],"h":"Penggubahnya wartawan sekaligus pemain biola yang memperdengarkan lagu ini pertama kali pada Kongres Pemuda II tahun 1928."},{"i":2907,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":3,"q":"Lagu Kebangsaan yang diiringi alat musik dinyanyikan …","e":"Pasal 60 UU Nomor 24 Tahun 2009 menyebut: “Lagu Kebangsaan yang diiringi alat musik, dinyanyikan lengkap satu strofe, dengan satu kali ulangan pada refrein.”\nCara cepat: Pakai musik: strofe dan refrein. Tanpa musik: stanza pertama dan ulang bait ketiga.","o":["hanya bagian refrein sebanyak dua kali","dua strofe dengan dua kali ulangan pada refrein","lengkap tiga stanza tanpa ulangan","satu stanza pertama, dengan satu kali ulangan pada bait ketiga","lengkap satu strofe, dengan satu kali ulangan pada refrein"],"s":[0,0,0,0,1],"w":["Menurut Pasal 60 UU Nomor 24 Tahun 2009, jawabannya “lengkap satu strofe, dengan satu kali ulangan pada refrein”, bukan “hanya bagian refrein sebanyak dua kali”.","Menurut Pasal 60 UU Nomor 24 Tahun 2009, jawabannya “lengkap satu strofe, dengan satu kali ulangan pada refrein”, bukan “dua strofe dengan dua kali ulangan pada refrein”.","Menurut Pasal 60 UU Nomor 24 Tahun 2009, jawabannya “lengkap satu strofe, dengan satu kali ulangan pada refrein”, bukan “lengkap tiga stanza tanpa ulangan”.","Menurut Pasal 60 UU Nomor 24 Tahun 2009, jawabannya “lengkap satu strofe, dengan satu kali ulangan pada refrein”, bukan “satu stanza pertama, dengan satu kali ulangan pada bait ketiga”. “satu stanza pertama, dengan satu kali ulangan pada bait ketiga” ada di ketentuan lain, Pasal 60 UU Nomor 24 Tahun 2009: “Lagu Kebangsaan yang tidak diiringi alat musik, dinyanyikan lengkap satu stanza pertama, dengan satu kali ulangan pada bait ketiga stanza pertama”","Benar. Ini sesuai Pasal 60 UU Nomor 24 Tahun 2009."],"h":"Pakai musik: strofe dan refrein. Tanpa musik: stanza pertama dan ulang bait ketiga."},{"i":2908,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":4,"q":"Lagu Kebangsaan yang tidak diiringi alat musik dinyanyikan …","e":"Pasal 60 UU Nomor 24 Tahun 2009 menyebut: “Lagu Kebangsaan yang tidak diiringi alat musik, dinyanyikan lengkap satu stanza pertama, dengan satu kali ulangan pada bait ketiga stanza pertama.”\nCara cepat: Pakai musik: strofe dan refrein. Tanpa musik: stanza pertama dan ulang bait ketiga.","o":["dua stanza dengan ulangan pada setiap bait","lengkap tiga stanza tanpa ulangan","lengkap satu strofe, dengan satu kali ulangan pada refrein","lengkap satu stanza pertama, dengan satu kali ulangan pada bait ketiga stanza pertama","hanya bait pertama sebanyak dua kali"],"s":[0,0,0,1,0],"w":["Menurut Pasal 60 UU Nomor 24 Tahun 2009, jawabannya “lengkap satu stanza pertama, dengan satu kali ulangan pada bait ketiga stanza pertama”, bukan “dua stanza dengan ulangan pada setiap bait”.","Menurut Pasal 60 UU Nomor 24 Tahun 2009, jawabannya “lengkap satu stanza pertama, dengan satu kali ulangan pada bait ketiga stanza pertama”, bukan “lengkap tiga stanza tanpa ulangan”.","Menurut Pasal 60 UU Nomor 24 Tahun 2009, jawabannya “lengkap satu stanza pertama, dengan satu kali ulangan pada bait ketiga stanza pertama”, bukan “lengkap satu strofe, dengan satu kali ulangan pada refrein”. “lengkap satu strofe, dengan satu kali ulangan pada refrein” ada di ketentuan lain, Pasal 60 UU Nomor 24 Tahun 2009: “Lagu Kebangsaan yang diiringi alat musik, dinyanyikan lengkap satu strofe, dengan satu kali ulangan pada refrein”","Benar. Ini sesuai Pasal 60 UU Nomor 24 Tahun 2009.","Menurut Pasal 60 UU Nomor 24 Tahun 2009, jawabannya “lengkap satu stanza pertama, dengan satu kali ulangan pada bait ketiga stanza pertama”, bukan “hanya bait pertama sebanyak dua kali”."],"h":"Pakai musik: strofe dan refrein. Tanpa musik: stanza pertama dan ulang bait ketiga."},{"i":2909,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":1,"q":"Setiap orang yang hadir saat Lagu Kebangsaan diperdengarkan atau dinyanyikan wajib …","e":"Pasal 62 UU Nomor 24 Tahun 2009 menyebut: “Setiap orang yang hadir pada saat Lagu Kebangsaan diperdengarkan dan/atau dinyanyikan, wajib berdiri tegak dengan sikap hormat.”\nCara cepat: Sikapnya sama seperti saat menghormati bendera: tegak dan hormat.","o":["duduk tegak dan diam","berdiri tegak dengan sikap hormat","menundukkan kepala","bertepuk tangan setelah lagu selesai","meletakkan tangan kanan di dada"],"s":[0,1,0,0,0],"w":["Menurut Pasal 62 UU Nomor 24 Tahun 2009, jawabannya “berdiri tegak dengan sikap hormat”, bukan “duduk tegak dan diam”.","Benar. Ini sesuai Pasal 62 UU Nomor 24 Tahun 2009.","Menurut Pasal 62 UU Nomor 24 Tahun 2009, jawabannya “berdiri tegak dengan sikap hormat”, bukan “menundukkan kepala”.","Menurut Pasal 62 UU Nomor 24 Tahun 2009, jawabannya “berdiri tegak dengan sikap hormat”, bukan “bertepuk tangan setelah lagu selesai”.","Menurut Pasal 62 UU Nomor 24 Tahun 2009, jawabannya “berdiri tegak dengan sikap hormat”, bukan “meletakkan tangan kanan di dada”."],"h":"Sikapnya sama seperti saat menghormati bendera: tegak dan hormat."},{"i":2910,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":2,"q":"Ketika Presiden menerima kunjungan kepala negara lain, lagu yang diperdengarkan lebih dahulu adalah …","e":"Pasal 63 UU Nomor 24 Tahun 2009 menyebut: “Dalam hal Presiden atau Wakil Presiden Republik Indonesia menerima kunjungan kepala negara atau kepala pemerintahan negara lain, lagu kebangsaan negara lain diperdengarkan lebih dahulu, selanjutnya Lagu Kebangsaan Indonesia Raya.”\nSelanjutnya diperdengarkan Lagu Kebangsaan Indonesia Raya.\nCara cepat: Tamu didahulukan sebagai bentuk penghormatan; tuan rumah menyusul.","o":["lagu daerah tempat penyambutan","kedua lagu kebangsaan bersamaan","Indonesia Raya","lagu kebangsaan negara lain","tidak ada lagu kebangsaan yang diperdengarkan"],"s":[0,0,0,1,0],"w":["Menurut Pasal 63 UU Nomor 24 Tahun 2009, jawabannya “lagu kebangsaan negara lain”, bukan “lagu daerah tempat penyambutan”.","Menurut Pasal 63 UU Nomor 24 Tahun 2009, jawabannya “lagu kebangsaan negara lain”, bukan “kedua lagu kebangsaan bersamaan”.","Menurut Pasal 63 UU Nomor 24 Tahun 2009, jawabannya “lagu kebangsaan negara lain”, bukan “Indonesia Raya”.","Benar. Ini sesuai Pasal 63 UU Nomor 24 Tahun 2009.","Menurut Pasal 63 UU Nomor 24 Tahun 2009, jawabannya “lagu kebangsaan negara lain”, bukan “tidak ada lagu kebangsaan yang diperdengarkan”."],"h":"Tamu didahulukan sebagai bentuk penghormatan; tuan rumah menyusul."},{"i":2911,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":4,"q":"Lagu Kebangsaan wajib diperdengarkan dan/atau dinyanyikan dalam hal-hal berikut, kecuali …","e":"Pasal 59 UU Nomor 24 Tahun 2009: Lagu Kebangsaan wajib diperdengarkan dan/atau dinyanyikan: untuk menghormati Presiden dan/atau Wakil Presiden; untuk menghormati Bendera Negara pada waktu pengibaran atau penurunan Bendera Negara yang diadakan dalam upacara; dalam acara resmi yang diselenggarakan oleh pemerintah; dalam acara pembukaan sidang paripurna Majelis Permusyawaratan Rakyat, Dewan Perwakilan Rakyat, Dewan Perwakilan Rakyat Daerah dan Dewan Perwakilan Daerah; untuk menghormati kepala negara atau kepala pemerintahan negara sahabat dalam kunjungan resmi; dalam acara atau kegiatan olahraga internasional;; dalam acara ataupun kompetisi ilmu pengetahuan, teknologi, dan seni internasional yang diselenggarakan di Indonesia.\n“sebagai pernyataan rasa kebangsaan” tidak termasuk di dalamnya.\nMenyanyikan Lagu Kebangsaan sebagai pernyataan rasa kebangsaan diperbolehkan (Pasal 59 ayat 2), tetapi tidak diwajibkan.\nCara cepat: Wajib: acara kenegaraan, penghormatan kepada kepala negara dan bendera dalam upacara, sidang paripurna, olahraga dan kompetisi internasional. Boleh (tidak wajib): ungkapan kebangsaan dan program pendidikan.","o":["sebagai pernyataan rasa kebangsaan","dalam acara resmi yang diselenggarakan oleh pemerintah","untuk menghormati Presiden dan/atau Wakil Presiden","dalam acara atau kegiatan olahraga internasional","untuk menghormati kepala negara atau kepala pemerintahan negara sahabat dalam kunjungan resmi"],"s":[1,0,0,0,0],"w":["Benar. Ini tidak termasuk dalam Pasal 59 UU Nomor 24 Tahun 2009.","Ini disebut dalam Pasal 59 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Ini disebut dalam Pasal 59 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Ini disebut dalam Pasal 59 UU Nomor 24 Tahun 2009, jadi bukan jawabannya.","Ini disebut dalam Pasal 59 UU Nomor 24 Tahun 2009, jadi bukan jawabannya."],"h":"Wajib: acara kenegaraan, penghormatan kepada kepala negara dan bendera dalam upacara, sidang paripurna, olahraga dan kompetisi internasional. Boleh (tidak wajib): ungkapan kebangsaan dan program pendidikan."},{"i":2912,"k":"skd.twk.bendera-bahasa-lagu","j":"pilgan","v":2,"q":"Menurut UU Nomor 24 Tahun 2009, perbuatan yang dilarang terhadap Lagu Kebangsaan adalah …","e":"Pasal 64 UU Nomor 24 Tahun 2009 menyebut: “Setiap orang dilarang: menggunakan Lagu Kebangsaan untuk iklan dengan maksud untuk tujuan komersial”\nMenyanyikan tanpa iringan, instrumental, atau lengkap tiga stanza diatur dalam Pasal 60 dan 61.\nCara cepat: Larangannya hanya soal mengubah untuk menghina dan memakai untuk tujuan komersial. Variasi cara menyanyi justru diatur dan diperbolehkan.","o":["memperdengarkan Lagu Kebangsaan secara instrumental","menyanyikan Lagu Kebangsaan tanpa iringan alat musik","memperdengarkan Lagu Kebangsaan dalam program pendidikan","menyanyikan Lagu Kebangsaan lengkap tiga stanza","menggunakan Lagu Kebangsaan untuk iklan dengan maksud untuk tujuan komersial"],"s":[0,0,0,0,1],"w":["Menurut Pasal 64 UU Nomor 24 Tahun 2009, jawabannya “menggunakan Lagu Kebangsaan untuk iklan dengan maksud untuk tujuan komersial”, bukan “memperdengarkan Lagu Kebangsaan secara instrumental”.","Menurut Pasal 64 UU Nomor 24 Tahun 2009, jawabannya “menggunakan Lagu Kebangsaan untuk iklan dengan maksud untuk tujuan komersial”, bukan “menyanyikan Lagu Kebangsaan tanpa iringan alat musik”.","Menurut Pasal 64 UU Nomor 24 Tahun 2009, jawabannya “menggunakan Lagu Kebangsaan untuk iklan dengan maksud untuk tujuan komersial”, bukan “memperdengarkan Lagu Kebangsaan dalam program pendidikan”.","Menurut Pasal 64 UU Nomor 24 Tahun 2009, jawabannya “menggunakan Lagu Kebangsaan untuk iklan dengan maksud untuk tujuan komersial”, bukan “menyanyikan Lagu Kebangsaan lengkap tiga stanza”.","Benar. Ini sesuai Pasal 64 UU Nomor 24 Tahun 2009."],"h":"Larangannya hanya soal mengubah untuk menghina dan memakai untuk tujuan komersial. Variasi cara menyanyi justru diatur dan diperbolehkan."}];
